const idle = ["conn1"];
const waiting = [];
const log = [];

async function acquire(who) {
  if (idle.length > 0) return idle.pop();
  log.push(`${who} waits`);
  return new Promise((resolve) => waiting.push(resolve));
}
function release(conn) {
  const next = waiting.shift();
  if (next) next(conn);
  else idle.push(conn);
}

async function request(who) {
  const conn = await acquire(who);
  log.push(`${who} runs`);
  await Promise.resolve();
  release(conn);
}

await Promise.all([request("A"), request("B"), request("C")]);
console.log(log.join(", "));

