function lsnToBigInt(lsn) {
  const [high, low] = lsn.split("/");
  return (BigInt(`0x${high}`) << 32n) + BigInt(`0x${low}`);
}

function pickReplica(replicas, needed) {
  const target = lsnToBigInt(needed);
  const ready = replicas.find((r) => lsnToBigInt(r.replayed) >= target);
  return ready ? ready.name : "primary";
}

const replicas = [
  { name: "replica-a", replayed: "0/7000900" },
  { name: "replica-b", replayed: "0/7000A28" },
];
