function keep(days) {
  const sorted = [...days].sort((a, b) => b - a);
  const kept = new Set(sorted.slice(0, 7));
  const weeksKept = new Set([...kept].map((d) => Math.floor(d / 7)));
  let extraWeeks = 0;
  for (const day of sorted) {
    const week = Math.floor(day / 7);
    if (extraWeeks === 4) break;
    if (!weeksKept.has(week)) {
      kept.add(day);
      weeksKept.add(week);
      extraWeeks++;
    }
  }
  return [...kept].sort((a, b) => b - a);
}

const days = Array.from({ length: 40 }, (_, i) => 40 - i); // days 40 down to 1
console.log(keep(days));

