function lossMinutes(backups, accident) {
  const minutes = (hhmm) => {
    const [h, m] = hhmm.split(":").map(Number);
    return h * 60 + m;
  };
  const at = minutes(accident);
  const before = backups.map(minutes).filter((t) => t <= at);
  return before.length === 0 ? null : at - Math.max(...before);
}

